#include <iostream>
#include <string>
#include <vector>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int k, n;
    if (!(cin >> k >> n)) return 0;

    string alien, message;
    cin >> alien >> message;

    bool present[256] = {false};
    for (char c : alien) {
        present[static_cast<unsigned char>(c)] = true;
    }

    bool valid = true;
    for (char c : message) {
        if (!present[static_cast<unsigned char>(c)]) {
            valid = false;
            break;
        }
    }

    if (valid) {
        cout << "S\n";
    } else {
        cout << "N\n";
    }

    return 0;
}
